              type="text" 
              value={encontroId} 
              onChange={(e) => setEncontroId(e.target.value)} 
            />
          </div>
          <div className="form-group">
            <label>Participante (X-Usuario):</label>
            <select value={usuarioId} onChange={(e) => setUsuarioId(e.target.value)}>
