          <div style={{ margin: '1rem 0', padding: '1rem', border: '2px dashed #cbd5e1', borderRadius: '8px' }}>
            <div id="reader" style={{ width: '100%' }}></div>
            <p style={{ fontSize: '0.875rem', color: '#64748b', marginTop: '0.5rem', textAlign: 'center' }}>
              Aponte a câmera para o QR Code exibido pela organização.
            </p>
          </div>
        )}

        <form onSubmit={handleSubmeter}>
          <div className="form-group">
            <label>Código do Encontro (6 caracteres):</label>
            <input 
              type="text" 
              placeholder="Ex: K7M2QX" 
              value={codigo} 
              maxLength={6}
              onChange={(e) => setCodigo(e.target.value.toUpperCase())} 
              style={{ fontSize: '1.5rem', fontFamily: 'monospace', textTransform: 'uppercase' }}
            />
          </div>

          <button type="submit" className="primary" disabled={loading}>
            {loading ? 'Enviando...' : (isOnline ? 'Confirmar Presença' : 'Registrar Offline')}
          </button>
        </form>
      </div>

      {mensagem && (
        <div className="alert alert-success">
          {mensagem}
        </div>
      )}

      {erro && (
        <div className="alert alert-error">
          <strong>Erro ao registrar presença:</strong> {erro}
        </div>
      )}

      {offlineQueue.length > 0 && isOnline && (
        <div className="card" style={{ background: '#fffbeb' }}>
          <h3>Fila Offline</h3>
          <p>Existem presenças armazenadas offline aguardando envio.</p>
          <button onClick={sincronizarFila}>Sincronizar Agora</button>
        </div>
      )}
    </div>
  );
}

